const items = $input.all();
if (!items || items.length === 0) {
  const wanted = $('Config').first().json['Channel'];
  throw new Error(`No channel found named "${wanted}". It must match channels.name exactly (Islam / Geopolitics / Kids).`);
}
const channel = items[0].json;
return [{ json: {
  channel_id: channel.id,
  channel_name: channel.name,
  niche: channel.niche,
  brand_voice: channel.brand_voice
} }];

function fnv1a(str) {
  let h = 0x811c9dc5;
  for (let i = 0; i < str.length; i++) {
    h ^= str.charCodeAt(i);
    h = Math.imul(h, 0x01000193);
  }
  return (h >>> 0).toString(16).padStart(8, '0');
}

const niche = $('Pick Channel Row').first().json.niche;
const topicTitle = $('Pick Topic Row').first().json.topic_title;

const system = `You are the Research agent. Build a sourced dossier for one topic before any script
gets written. Nothing you produce here is treated as ground truth unless it has a status.

Topic: ${topicTitle}
Channel niche: ${niche}

For every factual claim relevant to this topic:
1. State the claim plainly.
2. List the source(s) — prefer primary sources (official documentation, regulatory
   filings, court records, company statements) over secondary (news coverage) over
   tertiary (aggregators, forums, other YouTube videos).
3. Mark status: verified (2+ independent credible sources agree), conflicting
   (credible sources disagree — note the disagreement, don't silently pick a side),
   or unsupported (no credible source found — this claim gets removed, not softened).

Do not fabricate a source. If you're not confident a source exists, say so and mark
the claim unsupported rather than inventing a plausible-sounding citation.

Flag anything needing extra scrutiny: numbers, dates, named entities, geography,
quotes attributed to real people.

Output: a dossier with all claims grouped by status, plus a short "story potential"
note — the actual narrative arc here, given what's verifiable.

Respond with JSON only, no prose outside the JSON, matching exactly this shape:
{
  "claims": [
    { "claim": string, "status": "verified" | "conflicting" | "unsupported", "sources": [ { "title": string, "url": string, "tier": "primary" | "secondary" | "tertiary" } ], "flag_for_scrutiny": boolean }
  ],
  "story_potential": string,
  "dossier_status": "complete" | "needs_review"
}
Set dossier_status to "needs_review" if too many claims came back unsupported or conflicting to responsibly proceed to scripting.`;

return [{ json: { system, topic_title: topicTitle, input_hash: fnv1a(system) } }];

function fnv1a(str) {
  let h = 0x811c9dc5;
  for (let i = 0; i < str.length; i++) {
    h ^= str.charCodeAt(i);
    h = Math.imul(h, 0x01000193);
  }
  return (h >>> 0).toString(16).padStart(8, '0');
}

// Pasted by hand from your own Claude chat — no billed API call happened,
// so there's no `usage` object and no per-token cost to compute here.
const raw = $input.first().json["Claude's JSON response"] || '';
let parsed = null;
let parseError = null;
try {
  const match = raw.match(/\{[\s\S]*\}/);
  parsed = JSON.parse(match ? match[0] : raw);
} catch (e) {
  parseError = e.message;
}

const claims = Array.isArray(parsed?.claims) ? parsed.claims : [];
const sources = claims.flatMap(c => Array.isArray(c.sources) ? c.sources : []);
const status = parseError ? 'needs_review' : (parsed?.dossier_status === 'needs_review' ? 'needs_review' : 'complete');

return [{ json: {
  claims,
  sources,
  status,
  story_potential: parsed?.story_potential || null,
  raw_text: raw,
  parse_error: parseError,
  estimated_cost: 0,
  output_hash: fnv1a(raw)
} }];

const dossier = $('Parse Dossier JSON').first().json;
return [{ json: {
  topic: $('Pick Topic Row').first().json.topic_title,
  channel: $('Pick Channel Row').first().json.channel_name,
  dossier_status: dossier.status,
  claims_verified: dossier.claims.filter(c => c.status === 'verified').length,
  claims_conflicting: dossier.claims.filter(c => c.status === 'conflicting').length,
  claims_unsupported: dossier.claims.filter(c => c.status === 'unsupported').length,
  story_potential: dossier.story_potential,
  claims: dossier.claims,
  parse_error: dossier.parse_error || undefined,
  raw_model_output_if_parse_failed: dossier.parse_error ? dossier.raw_text : undefined
} }];
